contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint minSum, uint amount) public payable {
        require(amount > 0);
        require(amount > minSum);
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethBefore = address(c).balance;
        bool reverted;
        c.Collect(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(
            !reverted &&
            c.balances(address(this)) == balBefore &&
            address(c).balance == ethBefore
        );
    }
    receive() external payable { }
}

